// Arma el paquete del lote: una solicitud por consulta, con un custom_id para reconocerla.
// El manual lleva el señalador con ttl de 1 hora: el lote puede tardar más de 5 minutos.
const manual = $('El manual (parte fija)').first().json.parte_fija;
const requests = $input.all().map((item, i) => ({
  custom_id: 'consulta-' + (i + 1),
  params: {
    model: 'claude-sonnet-5',
    max_tokens: 1024,
    thinking: { type: 'disabled' },
    system: [{ type: 'text', text: manual, cache_control: { type: 'ephemeral', ttl: '1h' } }],
    messages: [{
      role: 'user',
      content: 'Remitente: ' + item.json.remitente + '\nFecha: ' + item.json.fecha + '\nConsulta:\n' + item.json.consulta
    }]
  }
}));
return [{ json: { paquete: { requests } } }];

// El recibo del envío: t0.
const r = $input.first().json;
return [{ json: {
  id_del_lote: r.id,
  estado: r.processing_status,
  enviado: r.created_at,
  vence: r.expires_at,
  mensaje: 'Lote enviado. Retiralo con el flujo 3 cuando el estado sea ended (hasta 24 horas; casi siempre, menos de 1 hora).'
} }];
